<?php
/**
 * Starter editorial highlights for seven destinations.
 * Content is sourced from official Tahiti Tourisme pages; editors should review before publication.
 */
if (!defined('ABSPATH')) { exit; }

function gtc_seed_destination_highlights(): void {
    if (!current_user_can('manage_options') || get_option('gtc_destination_highlights_seeded')) { return; }
    $items = [
        // Tahiti
        ['tahiti','faarumai-waterfalls','The Three Waterfalls of Faarumai','NATURE','A trio of waterfalls set within Tahiti’s lush east-coast landscape.','The Faarumai waterfall area is a notable nature stop on Tahiti’s east coast. Vaimahuta is the first waterfall, with the other cascades reached farther along the walking route. Check local access conditions before visiting.','Tahiti','https://www.google.com/maps/search/?api=1&query=Faarumai+Waterfalls+Tahiti','https://tahititourisme.pf/en-pf/islands-and-archipelagos/the-society-islands/tahiti/escape-to-tahiti/','hidden-gem'],
        ['tahiti','teahupoo-peninsula','Teahupo’o & Tahiti Iti','COAST & CULTURE','A dramatic peninsula of cliffs, villages and ocean scenery.','Tahiti Iti is the smaller peninsula connected to Tahiti Nui. The area around Teahupo’o is known for its powerful surf, coastal scenery and excursions to nearby natural landscapes. Visitors should follow local guidance and respect ocean conditions.','Tahiti Iti · Teahupo’o','https://www.google.com/maps/search/?api=1&query=Teahupoo+Tahiti','https://tahititourisme.pf/en-pf/islands-and-archipelagos/the-society-islands/tahiti/what-to-do-in-tahiti/exploring-tahitis-peninsula/','landmark'],
        ['tahiti','vaipahi-water-gardens','Vaipahi Water Gardens','GARDENS','A peaceful botanical stop among tropical plants and water features.','Vaipahi is part of Tahiti’s scenic south-coast itinerary, known for its gardens and lush surroundings. Combine the visit with a broader exploration of the island’s natural and cultural stops.','Tahiti · South coast','https://www.google.com/maps/search/?api=1&query=Vaipahi+Water+Gardens+Tahiti','https://tahititourisme.pf/en-pf/islands-and-archipelagos/the-society-islands/tahiti/escape-to-tahiti/','landmark'],
        // Moorea
        ['moorea','cooks-bay','Cook’s Bay','BAYS & LANDSCAPE','A fjord-like bay framed by Mount Rotui and the island’s green peaks.','Cook’s Bay, also called Paopao Bay, is a scenic inlet with Mount Rotui rising above it. The bay is a hub for excursions, restaurants and local shops, making it a useful place to explore on a Moorea visit.','Moorea · Paopao','https://www.google.com/maps/search/?api=1&query=Cooks+Bay+Moorea','https://tahititourisme.pf/en-pf/islands-and-archipelagos/the-society-islands/moorea/what-to-do-in-moorea/','landmark'],
        ['moorea','opunohu-viewpoint','Opunohu Lookout','VIEWPOINT','A panoramic viewpoint looking across Moorea’s twin bays and Mount Rotui.','The Opunohu viewpoint offers a wide panorama over Opunohu Bay and Cook Bay, with Mount Rotui between them. Visiting earlier or later in the day can help avoid haze and harsh light.','Moorea · Opunohu','https://www.google.com/maps/search/?api=1&query=Opunohu+Lookout+Moorea','https://tahititourisme.pf/en-pf/islands-and-archipelagos/the-society-islands/moorea/what-to-do-in-moorea/','landmark'],
        ['moorea','temae-beach','Temae Beach','BEACH','A public white-sand beach with shallow lagoon water and views toward Tahiti.','Temae Beach is a popular public beach on Moorea’s northeast coast. Its sandy shoreline and clear lagoon make it a favorite for swimming, snorkeling near shore and relaxing beneath coconut palms.','Moorea · Temae','https://www.google.com/maps/search/?api=1&query=Temae+Beach+Moorea','https://tahititourisme.pf/en-pf/islands-and-archipelagos/the-society-islands/moorea/what-to-do-in-moorea/','activity'],
        // Huahine
        ['huahine','maeva-archaeological-sites','Maeva Archaeological Area','CULTURAL HERITAGE','A remarkable concentration of marae and historic sites in northern Huahine.','Maeva is known for important marae and archaeological remains that help visitors learn about Polynesian history and culture. Explore respectfully and consider a local guide to understand the site’s significance.','Huahine · Maeva','https://www.google.com/maps/search/?api=1&query=Maeva+Marae+Huahine','https://tahititourisme.pf/en-pf/islands-and-archipelagos/the-society-islands/huahine/what-to-do-in-huahine/','culture'],
        ['huahine','faie-sacred-eels','Faie’s Sacred Eels','WILDLIFE & TRADITION','A distinctive local experience connected with stories and traditions of Huahine.','Faie is known for its sacred eels, a distinctive part of local visitor experiences and traditions. Observe respectfully and follow local guidance around wildlife.','Huahine · Faie','https://www.google.com/maps/search/?api=1&query=Faie+Sacred+Eels+Huahine','https://tahititourisme.pf/en-pf/islands-and-archipelagos/the-society-islands/huahine/what-to-do-in-huahine/','culture'],
        ['huahine','huahine-viewpoint','Huahine Scenic Lookout','SCENIC VIEW','A hillside viewpoint to appreciate Huahine’s bays, valleys and island greenery.','Huahine offers hikes to scenic viewpoints overlooking its landscape of bays, valleys and vegetation. Check route conditions and seek local advice for hikes.','Huahine','https://www.google.com/maps/search/?api=1&query=Huahine+viewpoint','https://tahititourisme.pf/en-pf/islands-and-archipelagos/the-society-islands/huahine/what-to-do-in-huahine/','activity'],
        // Raiatea
        ['raiatea','taputapuatea-marae','Taputapuātea Marae','UNESCO & CULTURE','A major sacred complex and UNESCO World Heritage site.','Taputapuātea is a major cultural and sacred site on Raiatea, recognized as a UNESCO World Heritage site in 2017. Interpretive information and guided visits can help explain its place in Polynesian history.','Raiatea · Opoa','https://www.google.com/maps/search/?api=1&query=Taputapuatea+Marae+Raiatea','https://tahititourisme.pf/en-pf/islands-and-archipelagos/the-society-islands/raiatea/what-to-do-in-raiatea/','culture'],
        ['raiatea','faaroa-river','Faaroa River','NATURE & EXPLORATION','Explore Raiatea’s inland scenery along its navigable river.','Raiatea is home to Polynesia’s navigable Faaroa River. Visitors can discover the river and surrounding lush landscape through locally offered excursions, following operator guidance.','Raiatea','https://www.google.com/maps/search/?api=1&query=Faaroa+River+Raiatea','https://tahititourisme.pf/en-pf/islands-and-archipelagos/the-society-islands/raiatea/what-to-do-in-raiatea/','activity'],
        ['raiatea','temehani-plateau','Mount Temehani','NATURE','A highland landscape associated with Raiatea’s endemic Apetahi flower.','Mount Temehani is associated with the Apetahi flower, which is endemic to Raiatea. This natural area is best explored with appropriate local information and respect for the environment.','Raiatea · Temehani','https://www.google.com/maps/search/?api=1&query=Mount+Temehani+Raiatea','https://tahititourisme.pf/en-pf/islands-and-archipelagos/the-society-islands/raiatea/what-to-do-in-raiatea/','hidden-gem'],
        // Taha'a
        ['taha-a','vanilla-farms','Taha’a Vanilla Farms','LOCAL CRAFT & FLAVOUR','Discover how the island’s famous vanilla is cultivated and prepared.','Taha’a is celebrated for vanilla. Visits to local cultivators can show the hand-pollination and drying process behind the fragrant pods. Confirm opening and tour availability with farms before visiting.','Taha’a','https://www.google.com/maps/search/?api=1&query=Vanilla+Farm+Tahaa','https://tahititourisme.pf/en-pf/islands-and-archipelagos/the-society-islands/tahaa/what-to-do-in-tahaa/','culture'],
        ['taha-a','coral-garden','Taha’a Coral Garden','LAGOON','A lagoon experience among coral formations and marine life.','Taha’a’s lagoon includes a coral garden that is listed among local places to explore. Choose responsible operators, respect reef life and follow conditions and guidance in the water.','Taha’a lagoon','https://www.google.com/maps/search/?api=1&query=Coral+Garden+Tahaa','https://tahititourisme.pf/en-pf/islands-and-archipelagos/the-society-islands/tahaa/what-to-do-in-tahaa/','activity'],
        ['taha-a','motu-ceran','Motu Céran','MOTU','A small lagoon islet on the eastern side of Taha’a.','Motu Céran is an islet on the eastern side of Taha’a, opposite Motu Atger. It is a lagoon destination; access and activities depend on local operators and conditions.','Taha’a lagoon · east side','https://www.google.com/maps/search/?api=1&query=Motu+Ceran+Tahaa','https://tahititourisme.pf/en-pf/islands-and-archipelagos/the-society-islands/tahaa/','hidden-gem'],
        // Rangiroa
        ['rangiroa','tiputa-pass','Tiputa Pass','MARINE LIFE','A celebrated pass where visitors may observe marine life from excursions.','Tiputa is one of Rangiroa’s reef passes and a recognized marine-life viewing and diving area. Wildlife sightings vary; use licensed local operators and follow their safety guidance.','Rangiroa · Tiputa','https://www.google.com/maps/search/?api=1&query=Tiputa+Pass+Rangiroa','https://tahititourisme.pf/en-pf/islands-and-archipelagos/tuamotu-islands/rangiroa/what-to-do-in-rangiroa/','activity'],
        ['rangiroa','blue-lagoon','The Blue Lagoon','LAGOON EXCURSION','A lagoon excursion destination known for its striking blue water.','The Blue Lagoon is among Rangiroa’s well-known excursion locations. Trips are typically arranged with local operators; confirm logistics, weather and access before planning a visit.','Rangiroa','https://www.google.com/maps/search/?api=1&query=Blue+Lagoon+Rangiroa','https://tahititourisme.pf/en-pf/islands-and-archipelagos/tuamotu-islands/rangiroa/what-to-do-in-rangiroa/','hidden-gem'],
        ['rangiroa','tiputa-dolphin-view','Dolphins at Tiputa','WILDLIFE','Watch for dolphins around the pass from suitable shore or excursion viewpoints.','Dolphins are known to be seen around Tiputa Pass. Wildlife is unpredictable, so sightings are never guaranteed; keep a respectful distance and do not disturb animals.','Rangiroa · Tiputa','https://www.google.com/maps/search/?api=1&query=Tiputa+Pass+Dolphins+Rangiroa','https://tahititourisme.pf/en-pf/islands-and-archipelagos/tuamotu-islands/rangiroa/what-to-do-in-rangiroa/','activity'],
        // Fakarava
        ['fakarava','garuae-pass','Garuae Pass','MARINE LANDSCAPE','The wide northern pass of Fakarava, known for its reef and marine ecosystem.','Garuae is the northern pass of Fakarava and is noted for its width and marine environment. Excursions and water activities should be arranged with qualified local operators and suited to conditions.','Fakarava · North','https://www.google.com/maps/search/?api=1&query=Garuae+Pass+Fakarava','https://tahititourisme.pf/en-pf/islands-and-archipelagos/tuamotu-islands/fakarava/what-to-do-in-fakarava/','landmark'],
        ['fakarava','tumakohua-pass','Tumakohua Pass','SOUTHERN ATOLL','A southern pass near the historic village of Tetamanu and a rich marine environment.','Tumakohua Pass lies in southern Fakarava near Tetamanu. The area is known for its marine life; travel there involves planning with local operators and checking conditions.','Fakarava · South','https://www.google.com/maps/search/?api=1&query=Tumakohua+Pass+Fakarava','https://tahititourisme.pf/en-pf/islands-and-archipelagos/tuamotu-islands/fakarava/what-to-do-in-fakarava/','activity'],
        ['fakarava','rotoava-village','Rotoava Village','LOCAL LIFE','Begin exploring Fakarava from its traditional northern village.','Rotoava is a traditional fishing village and a useful starting point for discovering daily life on Fakarava, local shops, services and nearby lagoon experiences.','Fakarava · Rotoava','https://www.google.com/maps/search/?api=1&query=Rotoava+Fakarava','https://tahititourisme.pf/en-pf/islands-and-archipelagos/tuamotu-islands/fakarava/escape-to-fakarava/','culture'],
    ];
    foreach ($items as $index => $item) {
        [$island, $slug, $title, $kicker, $excerpt, $body, $location, $map, $source, $type] = $item;
        if (get_page_by_path($slug, OBJECT, 'iot_highlight')) { continue; }
        $id = wp_insert_post([
            'post_type' => 'iot_highlight', 'post_status' => 'publish',
            'post_title' => $title, 'post_name' => $slug,
            'post_excerpt' => $excerpt,
            'post_content' => '<p>' . esc_html($body) . '</p>',
            'menu_order' => 20 + $index,
        ], true);
        if (is_wp_error($id) || !$id) { continue; }
        update_post_meta($id, 'gtc_highlight_location', sanitize_text_field($location));
        update_post_meta($id, 'gtc_highlight_kicker', sanitize_text_field($kicker));
        update_post_meta($id, 'gtc_highlight_map_url', esc_url_raw($map));
        update_post_meta($id, 'gtc_highlight_source_url', esc_url_raw($source));
        wp_set_object_terms($id, $island, 'iot_highlight_island', false);
        wp_set_object_terms($id, $type, 'iot_highlight_type', false);
    }
    update_option('gtc_destination_highlights_seeded', 1, false);
}
add_action('admin_init', 'gtc_seed_destination_highlights', 40);
